#include "hbf_eventlab/adapters/tensor_access_bridge.hpp"
#include "hbf_eventlab/statistics/collector.hpp"
#include <iostream>
using namespace hbf_eventlab;
namespace {
void check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
template<class F>void rejects(F f){try{f();}catch(const std::exception&){return;}throw std::runtime_error("missing rejection");}
SimulationConfiguration config(std::size_t capacity=64){SimulationConfiguration c;c.device.geometry.host_channels=1;c.host.max_resident_fragments=capacity;return c;}
std::vector<TensorRegion> regions(std::uint64_t bytes=8192){return {{"weight",GlobalByteAddress{},bytes,1}};}
void done(TensorAccessBridge& b,bool success=true){const auto r=b.finish();check(r.run.status==RunStatus::Completed,r.run.explanation.c_str());check(r.run.workload_success==success,"final logical outcome");check(r.run.host.drained()&&r.run.device.drained(),"both endpoints drained");}
void round_trip(){TensorAccessBridge b(resolve_configuration(config()),regions());check(b.initialize("weight").success,"ordinary initialization");auto r=b.access("weight",0,8192,Tick{1000});check(r.success&&r.finished_globals==2,"symbolic tensor read checked");done(b);}
void backpressure(){TensorAccessBridge b(resolve_configuration(config()),regions());auto r=b.initialize("weight");check(r.success&&r.capacity_rejections>0&&r.registered_globals==2,"resident budget retries through capacity feedback");check(b.session().input_capacity().resident==0,"budget returned");done(b);}
void timing(){StatisticsCollector stats;TensorAccessBridge b(resolve_configuration(config()),regions(),{},&stats);auto w=b.initialize("weight");auto r=b.access("weight",0,8192,Tick{12345});check(r.success&&r.offered.value==w.completed->value+12345,"fixed compute adds to simulated completion");
    for(const auto& [id,g]:stats.globals())if(g.op==Op::Read)check(g.offered==r.offered&&g.registered&&!(g.registered.value()<r.offered),"original offered time survives backpressure");done(b);}
void zero_compute(){TensorAccessBridge b(resolve_configuration(config()),regions(4096));auto w=b.initialize("weight");auto r=b.access("weight",0,64);check(r.success&&r.offered==*w.completed,"zero compute creates causal request at same tick");auto r2=b.access("weight",64,64);check(r2.success&&r2.offered==*r.completed,"repeated callback boundaries");done(b);}
void aggregated(){StatisticsCollector stats;TensorAccessBridge b(resolve_configuration(config(128)),regions(),{1024},&stats);check(b.initialize("weight").success,"initialization split into globals");auto r=b.access("weight",0,8192);Tick maximum;
    for(const auto& [id,g]:stats.globals())if(g.op==Op::Read){check(g.finished.has_value(),"every child finished");if(maximum<*g.finished)maximum=*g.finished;}
    check(r.success&&r.finished_globals==8&&r.completed==maximum,"GPU parent waits for max of all logical Global results");done(b);}
void multi_channel(){auto c=config(128);c.device.geometry.host_channels=2;TensorAccessBridge b(resolve_configuration(c),regions());check(b.initialize("weight").success,"one full page per channel");check(b.access("weight",0,8192).success,"global routing uses existing host");done(b);}
void identity(){auto c=config(128);TensorAccessBridge b(resolve_configuration(c),{{"a",GlobalByteAddress{},4096,7},{"b",GlobalByteAddress{4096},4096,7}});check(b.initialize("a").success&&b.initialize("b").success,"one block shares one immutable content identity");check(b.access("a",0,4096).success&&b.access("b",0,4096).success,"page-dependent tokens retain content");rejects([&]{b.initialize("a");});done(b);}
void range(){TensorAccessBridge b(resolve_configuration(config()),regions());rejects([&]{b.access("missing",0,64);});rejects([&]{b.access("weight",1,64);});rejects([&]{b.access("weight",0,0);});rejects([&]{b.access("weight",8192,64);});check(b.session().host().results().empty(),"bad range has no registration");done(b);}
void registry(){auto c=resolve_configuration(config());rejects([&]{TensorAccessBridge b(c,regions(),{1});});rejects([&]{TensorAccessBridge b(c,{{"a",GlobalByteAddress{},4096,1},{"a",GlobalByteAddress{32768},4096,1}});});rejects([&]{TensorAccessBridge b(c,{{"a",GlobalByteAddress{},4096,1},{"b",GlobalByteAddress{},4096,1}});});rejects([&]{TensorAccessBridge b(c,{{"a",GlobalByteAddress{},4096,1},{"b",GlobalByteAddress{4096},4096,2}});});rejects([&]{TensorAccessBridge b(c,{{"a",GlobalByteAddress{UINT64_MAX-63},128,1}});});}
void too_large(){TensorAccessBridge b(resolve_configuration(config(32)),regions());rejects([&]{b.initialize("weight");});check(b.session().host().results().empty(),"oversized atomic chunk rejected before events");done(b);}
void timeout(){auto c=config(32);c.host.max_timeout_retries=0;TensorAccessBridge b(resolve_configuration(c),regions(4096),{2048});auto r=b.initialize("weight");check(r.complete&&!r.success&&r.unsubmitted_bytes==2048,"partial DLU budget timeout is not fabricated success");check(b.session().host().statistics().assembly_timeout_errors>0,"real timeout path used");done(b,false);}
void stalled(){TensorAccessBridge b(resolve_configuration(config()),{{"later",GlobalByteAddress{4096},4096,1}});auto r=b.initialize("later");check(!r.complete&&r.stop==RunStatus::WaitingForInput,"missing predecessor remains blocked");check(b.finish().run.status==RunStatus::Stalled,"closed unfinished input reported");}
void limit(){auto c=config();c.run.events.total_events=2;TensorAccessBridge b(resolve_configuration(c),regions());auto r=b.initialize("weight");check(!r.complete&&!r.success&&r.stop==RunStatus::LimitReached,"safety limit not access success");check(b.finish().run.status==RunStatus::LimitReached,"closing never resets budget");}
void replay(){auto c=config();c.faults.fail_sequence={0,0};TensorAccessBridge b(resolve_configuration(c),regions(4096));check(b.initialize("weight").success,"host merged replay succeeds");check(b.session().host().statistics().recovery_tasks==1&&b.session().host().statistics().replay_passes==2,"same host recovery task");check(b.access("weight",0,4096).success,"recovered content read");done(b);}
void failure(){auto c=config();c.faults.persistent_page=0;TensorAccessBridge b(resolve_configuration(c),regions());auto r=b.initialize("weight");check(r.complete&&!r.success&&r.registered_globals==1&&r.unsubmitted_bytes==4096,"failure stops unregistered suffix");rejects([&]{b.access("weight",0,64);});done(b,false);}
void no_retention(){auto c=config();c.host.retained_fragments=0;c.faults.fail_sequence={0};TensorAccessBridge b(resolve_configuration(c),regions(4096));auto r=b.initialize("weight");check(r.complete&&!r.success,"bridge never invents recovery data");done(b,false);}
void observer(){auto run=[](IStatisticsSink* sink){TensorAccessBridge b(resolve_configuration(config()),regions(),{},sink);const auto w=b.initialize("weight");const auto r=b.access("weight",0,8192,Tick{101});done(b);return std::make_pair(w.completed,r.completed);};StatisticsCollector stats;check(run(nullptr)==run(&stats),"statistics do not alter timeline");}
void burst(){auto c=config();c.host.writes=WriteCommandMode::Burst4096;TensorAccessBridge b(resolve_configuration(c),regions(4096));check(b.initialize("weight").success&&b.session().host().statistics().handed==1,"configured Host burst retained");check(b.access("weight",0,64).success,"burst init and ordinary read");done(b);}
void reentrant(){TensorAccessBridge b(resolve_configuration(config()),regions(4096));b.set_trace([&](const auto&){rejects([&]{b.access("weight",0,64);});rejects([&]{b.finish();});});check(b.initialize("weight").success,"callback rejects recursive gate");done(b);}
void closed(){TensorAccessBridge b(resolve_configuration(config()),regions());done(b);rejects([&]{b.access("weight",0,64);});check(b.finish().run.status==RunStatus::Completed,"idempotent finish");}
void failure_drain(){auto c=config(128);c.faults.persistent_page=0;TensorAccessBridge b(resolve_configuration(c),regions(12288));auto r=b.initialize("weight");check(r.complete&&!r.success&&r.registered_globals==2&&r.finished_globals==2&&r.unsubmitted_bytes==4096,"all registered children terminal before failed gate returns");done(b,false);}
void input_contract(){auto c=config();c.host.max_logical_fragments=64;TensorAccessBridge b(resolve_configuration(c),regions(4096));check(b.initialize("weight").success,"input budget baseline");const auto r=b.access("weight",0,64);check(r.complete&&!r.success&&r.stop==RunStatus::ModelError&&r.registered_globals==0,"Host lifetime guard becomes explicit adapter input failure");check(b.session().host().results().size()==1,"no rejected child or Device error fabricated");done(b);}
void trace_error(){TensorAccessBridge b(resolve_configuration(config()),regions(4096));b.set_trace([](const auto& e){if(std::string(e.action)=="access-finished")throw std::runtime_error("observer failed");});const auto r=b.initialize("weight");check(!r.success&&r.stop==RunStatus::ImplementationError,"callback error cannot leave a successful parent");rejects([&]{b.access("weight",0,64);});}
}
int main(int argc,char** argv){const std::map<std::string,void(*)()> tests={{"round_trip",round_trip},{"backpressure",backpressure},{"timing",timing},{"zero_compute",zero_compute},{"aggregated",aggregated},{"multi_channel",multi_channel},{"identity",identity},{"range",range},{"registry",registry},{"too_large",too_large},{"timeout",timeout},{"stalled",stalled},{"limit",limit},{"replay",replay},{"failure",failure},{"no_retention",no_retention},{"observer",observer},{"burst",burst},{"reentrant",reentrant},{"closed",closed},{"failure_drain",failure_drain},{"input_contract",input_contract},{"trace_error",trace_error}};
    try{if(argc!=2)throw std::runtime_error("scenario required");
        tests.at(argv[1])();
        std::cout<<"PASS tensor_bridge "<<argv[1]<<'\n';}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
